=== FILE: tb/tb_mac8.v ===
// Self-checking scoreboard testbench for mac8.
// Reference model written from interface_spec.md (MAC-RESET, MAC-CLEAR, MAC-ACC,
// MAC-HOLD, MAC-SAT, MAC-STICKY), not from the RTL.
// Inputs are driven on the falling edge; outputs are compared 1 ns after the
// rising edge (and also 1 ns after the inputs change, to confirm the registered
// outputs do not follow the inputs between edges).
`timescale 1ns / 1ps
module tb_mac8;
  reg         clk   = 1'b0;
  reg         rst_n = 1'b0;
  reg         clr   = 1'b0;
  reg         en    = 1'b0;
  reg  [7:0]  a     = 8'd0;
  reg  [7:0]  b     = 8'd0;
  wire [23:0] acc;
  wire        sat;

  mac8 dut (
    .clk  (clk),
    .rst_n(rst_n),
    .clr  (clr),
    .en   (en),
    .a    (a),
    .b    (b),
    .acc  (acc),
    .sat  (sat)
  );

  always #5 clk = ~clk;

  localparam [31:0] ACC_MAX = 32'h00FFFFFF;

  // ---------------- reference model state ----------------
  reg [23:0] m_acc   = 24'd0;
  reg        m_sat   = 1'b0;
  reg        m_valid = 1'b0;   // model state is known once a reset edge was seen
  reg [31:0] m_prod  = 32'd0;
  reg [31:0] m_sum   = 32'd0;

  // ---------------- scoreboard counters ----------------
  integer n_pass     = 0;
  integer n_fail     = 0;
  integer n_cycle    = 0;
  integer n_reported = 0;

  // ---------------- corner counters ----------------
  integer c_sat          = 0;  // saturation events (sum > 0xFFFFFF)
  integer c_sticky       = 0;  // non-clear, non-reset edges with flag already 1
  integer c_rst_en       = 0;  // reset edge with en high
  integer c_clr_en       = 0;  // clear edge with en high
  integer c_hold         = 0;  // en low, clr low, non-zero state
  integer c_exact_max    = 0;  // total reached exactly 0xFFFFFF without saturating
  integer c_zero_at_max  = 0;  // zero product accumulated at 0xFFFFFF, flag 0
  integer c_clr_sat      = 0;  // clear while flag 1
  integer c_rst_sat      = 0;  // reset while flag 1
  integer c_hi_op        = 0;  // accumulate with an operand >= 128 (unsigned read)

  // ---------------- misc ----------------
  reg [31:0]       rng   = 32'h2545F491;
  reg [8*128-1:0]  nonce = {8*128{1'b0}};
  reg              nonce_ok = 1'b0;
  reg [7:0]        ch;
  integer          i;
  integer          k;
  reg              r_rst_n, r_clr, r_en;
  reg [7:0]        r_a, r_b;
  reg [31:0]       r1, r2;

  // xorshift32 step
  task rand_step;
    begin
      rng = rng ^ (rng << 13);
      rng = rng ^ (rng >> 17);
      rng = rng ^ (rng << 5);
    end
  endtask

  // Reference model: one rising edge, from the specification.
  task model_step;
    begin
      if (!rst_n) begin
        // MAC-RESET
        if (en) c_rst_en = c_rst_en + 1;
        if (m_valid && m_sat) c_rst_sat = c_rst_sat + 1;
        m_acc   = 24'd0;
        m_sat   = 1'b0;
        m_valid = 1'b1;
      end else if (!m_valid) begin
        // state unknown before the first reset; nothing to predict
      end else if (clr) begin
        // MAC-CLEAR: clear wins over an accumulate at the same edge
        if (en) c_clr_en = c_clr_en + 1;
        if (m_sat) c_clr_sat = c_clr_sat + 1;
        m_acc = 24'd0;
        m_sat = 1'b0;
      end else if (en) begin
        // MAC-ACC with MAC-SAT / MAC-STICKY
        if (m_sat) c_sticky = c_sticky + 1;
        if (a >= 8'd128 || b >= 8'd128) c_hi_op = c_hi_op + 1;
        m_prod = {24'd0, a} * {24'd0, b};
        m_sum  = {8'd0, m_acc} + m_prod;
        if (m_sum > ACC_MAX) begin
          m_acc = 24'hFFFFFF;
          m_sat = 1'b1;
          c_sat = c_sat + 1;
        end else begin
          if (m_acc == 24'hFFFFFF && m_prod == 32'd0 && !m_sat)
            c_zero_at_max = c_zero_at_max + 1;
          m_acc = m_sum[23:0];
          if (m_acc == 24'hFFFFFF && !m_sat)
            c_exact_max = c_exact_max + 1;
          // flag unchanged (sticky if already 1)
        end
      end else begin
        // MAC-HOLD
        if (m_acc != 24'd0 || m_sat) c_hold = c_hold + 1;
        if (m_sat) c_sticky = c_sticky + 1;
      end
    end
  endtask

  task report_mismatch;
    input integer phase;   // 0: between edges, 1: after rising edge
    begin
      n_fail = n_fail + 1;
      if (n_reported < 10) begin
        n_reported = n_reported + 1;
        if (phase == 0)
          $display("MISMATCH (between edges) after cycle %0d: inputs rst_n=%b clr=%b en=%b a=%0d b=%0d | dut acc=%h sat=%b | model acc=%h sat=%b",
                   n_cycle, rst_n, clr, en, a, b, acc, sat, m_acc, m_sat);
        else
          $display("MISMATCH (after edge) cycle %0d: inputs rst_n=%b clr=%b en=%b a=%0d b=%0d | dut acc=%h sat=%b | model acc=%h sat=%b",
                   n_cycle, rst_n, clr, en, a, b, acc, sat, m_acc, m_sat);
      end
    end
  endtask

  task check_outputs;
    input integer phase;
    begin
      if (m_valid) begin
        if (acc === m_acc) n_pass = n_pass + 1;
        else report_mismatch(phase);
        if (sat === m_sat) n_pass = n_pass + 1;
        else report_mismatch(phase);
      end
    end
  endtask

  // One clock cycle: drive on the falling edge, check, edge, model, check.
  task cycle;
    input       i_rst_n;
    input       i_clr;
    input       i_en;
    input [7:0] i_a;
    input [7:0] i_b;
    begin
      @(negedge clk);
      rst_n = i_rst_n;
      clr   = i_clr;
      en    = i_en;
      a     = i_a;
      b     = i_b;
      #1;
      check_outputs(0);
      @(posedge clk);
      n_cycle = n_cycle + 1;
      model_step;
      #1;
      check_outputs(1);
    end
  endtask

  task acc_repeat;
    input integer     count;
    input [7:0]       i_a;
    input [7:0]       i_b;
    integer j;
    begin
      for (j = 0; j < count; j = j + 1)
        cycle(1'b1, 1'b0, 1'b1, i_a, i_b);
    end
  endtask

  task corner_check;
    input integer count;
    input integer id;
    begin
      if (count > 0) n_pass = n_pass + 1;
      else begin
        n_fail = n_fail + 1;
        $display("CORNER NOT REACHED: id %0d (count 0)", id);
      end
    end
  endtask

  initial begin
    // ---- nonce ----
    if ($value$plusargs("NIRMAAN_NONCE=%s", nonce)) nonce_ok = 1'b1;
    else if ($value$plusargs("nirmaan_nonce=%s", nonce)) nonce_ok = 1'b1;
    else if ($value$plusargs("NONCE=%s", nonce)) nonce_ok = 1'b1;
    else if ($value$plusargs("nonce=%s", nonce)) nonce_ok = 1'b1;
    if (!nonce_ok) begin
      $display("ERROR: no nonce plusarg found");
      n_fail = n_fail + 1;
    end

    // ---- S1: reset wins over an accumulate offered at the same edge ----
    cycle(1'b0, 1'b0, 1'b1, 8'd255, 8'd255);
    cycle(1'b0, 1'b0, 1'b1, 8'd255, 8'd255);
    cycle(1'b0, 1'b1, 1'b1, 8'd255, 8'd255);

    // ---- S2: basic unsigned accumulation ----
    cycle(1'b1, 1'b0, 1'b1, 8'd3,   8'd4);    // 12
    cycle(1'b1, 1'b0, 1'b1, 8'd10,  8'd20);   // 212
    cycle(1'b1, 1'b0, 1'b1, 8'd0,   8'd200);  // 212
    cycle(1'b1, 1'b0, 1'b1, 8'd255, 8'd1);    // 467 (unsigned 255)
    cycle(1'b1, 1'b0, 1'b1, 8'd128, 8'd2);    // 723
    cycle(1'b1, 1'b0, 1'b1, 8'd200, 8'd200);  // 40723

    // ---- S3: hold with operands present ----
    cycle(1'b1, 1'b0, 1'b0, 8'd255, 8'd255);
    cycle(1'b1, 1'b0, 1'b0, 8'd17,  8'd99);
    cycle(1'b1, 1'b0, 1'b0, 8'd255, 8'd255);
    cycle(1'b1, 1'b0, 1'b0, 8'd1,   8'd1);

    // ---- S4: clear wins over accumulate; then accumulate again ----
    cycle(1'b1, 1'b1, 1'b1, 8'd255, 8'd255);
    cycle(1'b1, 1'b1, 1'b0, 8'd0,   8'd0);
    cycle(1'b1, 1'b0, 1'b1, 8'd7,   8'd9);    // 63

    // ---- S5: reset in the middle of a run ----
    cycle(1'b0, 1'b0, 1'b1, 8'd17,  8'd3);
    cycle(1'b1, 1'b0, 1'b1, 8'd17,  8'd3);    // 51

    // ---- S6: reach exactly 0xFFFFFF without saturating ----
    cycle(1'b1, 1'b1, 1'b0, 8'd0, 8'd0);
    acc_repeat(258, 8'd255, 8'd255);           // 0xFFFD02
    cycle(1'b1, 1'b0, 1'b1, 8'd255, 8'd3);    // 0xFFFFFF, sat 0
    cycle(1'b1, 1'b0, 1'b1, 8'd0,   8'd0);    // stays 0xFFFFFF, sat 0
    cycle(1'b1, 1'b0, 1'b1, 8'd200, 8'd0);    // stays, sat 0
    cycle(1'b1, 1'b0, 1'b0, 8'd255, 8'd255);  // hold
    cycle(1'b1, 1'b0, 1'b1, 8'd1,   8'd1);    // saturates, sat 1

    // ---- S7: sticky flag ----
    cycle(1'b1, 1'b0, 1'b0, 8'd0,   8'd0);
    cycle(1'b1, 1'b0, 1'b0, 8'd9,   8'd9);
    cycle(1'b1, 1'b0, 1'b1, 8'd0,   8'd0);    // no overflow, flag stays 1
    cycle(1'b1, 1'b0, 1'b1, 8'd0,   8'd77);
    cycle(1'b1, 1'b0, 1'b1, 8'd255, 8'd255);
    cycle(1'b1, 1'b0, 1'b1, 8'd1,   8'd0);
    cycle(1'b1, 1'b0, 1'b0, 8'd3,   8'd3);

    // ---- S8: clear clears the flag ----
    cycle(1'b1, 1'b1, 1'b0, 8'd0,   8'd0);
    cycle(1'b1, 1'b0, 1'b1, 8'd1,   8'd1);    // 1, sat 0
    cycle(1'b1, 1'b0, 1'b0, 8'd0,   8'd0);

    // ---- S9: overflow far past the limit (wrap would give 0x00FD01) ----
    cycle(1'b1, 1'b1, 1'b0, 8'd0,   8'd0);
    acc_repeat(258, 8'd255, 8'd255);
    cycle(1'b1, 1'b0, 1'b1, 8'd255, 8'd2);    // 0xFFFF00
    cycle(1'b1, 1'b0, 1'b1, 8'd255, 8'd255);  // saturates
    cycle(1'b1, 1'b0, 1'b1, 8'd255, 8'd255);  // stays saturated

    // ---- S10: reset clears the flag ----
    cycle(1'b0, 1'b0, 1'b0, 8'd0,   8'd0);
    cycle(1'b1, 1'b0, 1'b1, 8'd2,   8'd2);    // 4, sat 0

    // ---- S11: clear wins over a saturating accumulate ----
    cycle(1'b1, 1'b1, 1'b0, 8'd0,   8'd0);
    acc_repeat(259, 8'd255, 8'd255);           // saturates on the 259th
    cycle(1'b1, 1'b1, 1'b1, 8'd255, 8'd255);  // clear wins: 0, sat 0
    cycle(1'b1, 1'b0, 1'b1, 8'd255, 8'd255);  // 65025, sat 0

    // ---- S12: seeded random traffic ----
    for (k = 0; k < 4000; k = k + 1) begin
      rand_step; r1 = rng;
      rand_step; r2 = rng;
      r_rst_n = (r1[9:0]   < 10'd3) ? 1'b0 : 1'b1;
      r_clr   = (r1[19:10] < 10'd4) ? 1'b1 : 1'b0;
      r_en    = (r1[23:20] < 4'd11) ? 1'b1 : 1'b0;
      r_a     = (r2[2:0] == 3'd0) ? 8'hFF : r2[15:8];
      r_b     = (r2[5:3] == 3'd0) ? 8'hFF : r2[23:16];
      cycle(r_rst_n, r_clr, r_en, r_a, r_b);
    end

    // ---- corner reach: the test fails itself if a corner was not exercised ----
    $display("CORNERS: sat=%0d sticky=%0d rst_en=%0d clr_en=%0d hold=%0d exact_max=%0d zero_at_max=%0d clr_sat=%0d rst_sat=%0d hi_op=%0d",
             c_sat, c_sticky, c_rst_en, c_clr_en, c_hold, c_exact_max,
             c_zero_at_max, c_clr_sat, c_rst_sat, c_hi_op);
    corner_check(c_sat,         1);
    corner_check(c_sticky,      2);
    corner_check(c_rst_en,      3);
    corner_check(c_clr_en,      4);
    corner_check(c_hold,        5);
    corner_check(c_exact_max,   6);
    corner_check(c_zero_at_max, 7);
    corner_check(c_clr_sat,     8);
    corner_check(c_rst_sat,     9);
    corner_check(c_hi_op,       10);

    $display("SUMMARY: %0d cycles, %0d checks passed, %0d failed", n_cycle, n_pass, n_fail);

    // ---- single verdict line ----
    $write("NIRMAAN-SIM ");
    for (i = 127; i >= 0; i = i - 1) begin
      ch = nonce[i*8 +: 8];
      if (ch != 8'd0) $write("%c", ch);
    end
    $display(" %0d passed, %0d failed", n_pass, n_fail);
    $finish;
  end
endmodule
=== END FILE ===
